cpp-oop.code:
struct Shape {
    virtual ~Shape() = default;           // needed for delete via base pointer
    virtual double area() const = 0;
};
struct Circle : Shape {
    double r;
    explicit Circle(double r) : r(r) {}
    double area() const override { return 3.14159 * r * r; }
};
std::unique_ptr<Shape> s = std::make_unique<Circle>(2.0);
s->area();   // calls Circle::area via dynamic dispatch

